contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint v, uint t) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (v)); require(v <= 1000000000000000000000000000000);
        require(address(this).balance >= v);
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.SetMinSum(1); if (__ESBMC_reverted()) return;
        c.Put{value: v}(t); if (__ESBMC_reverted()) return;
        (uint balBefore, uint utBefore) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        c.Collect(v); if (__ESBMC_reverted()) return;
        (uint balAfter, uint utAfter) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        assert(balAfter == balBefore && utAfter == utBefore);
    }
    receive() external payable {}
    fallback() external payable {}
}

