pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 v, uint256 t) internal {
        v = bound(v, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= v);
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.SetMinSum(1) {} catch { return; }
        try c.Put{value: v}(t) {} catch { return; }
        uint256 balBefore;
        uint256 utBefore;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { balBefore = __r0; utBefore = __r1; } catch { return; }
        try c.Collect(v) {} catch { return; }
        uint256 balAfter;
        uint256 utAfter;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { balAfter = __r0; utAfter = __r1; } catch { return; }
        assertTrue(balAfter == balBefore && utAfter == utBefore);
    }

    function testFuzz_run(uint256 v, uint256 t) public {
        _run(v, t);
    }

    receive() external payable {}

    fallback() external payable {}
}
